        }

        private static bool IsValidContainerRevision(RealtimeContainerRevision value)
        {
            if (value == null
                || value.ContainerId == Guid.Empty
                || value.Revision < 0)
            {
                return false;
            }

            return true;
        }

        private static bool IsDefined(RealtimeItemOperationKind value)
        {
            return (byte)value >= 1 && (byte)value <= 8;
        }
    }
